import {t,label,ui,markup,setText,initLanguage} from './language.mjs';
import {KEY,TYPES,GUIDE_CATEGORIES,today,yearsBefore,date,emptyData,envelope,readEnvelope,parseText,toText,patientById,ageMonths,vaccineStatus,vaccinationNeedsReview,stockStatus} from './core.mjs';
import {clinicGuideResults,clinicGuideReader} from './care-guides.mjs';
import {renderStaffDashboard,renderClinicTaskQueue,taskTitle} from './dashboard-ui.mjs';
import {icon} from './icons.mjs';
import {startMotion,animateWorkspace} from './motion.mjs';
import {setupAccounts,patientAccess} from './auth-ui.mjs';
import {api} from './accounts.mjs';
import {familyPanel,companionSettings,mountFamily} from './family-ui.mjs';
import {searchText,orderItems,pageItems} from './lists.mjs';
import {pagination} from './directory-ui.mjs';
const $=s=>document.querySelector(s);
initLanguage();
for(const link of document.querySelectorAll('#workspace-nav [data-page]'))link.querySelector('span').innerHTML=icon(link.dataset.page);
const FLOWER=markup("<svg class=\"flower-mark\" viewBox=\"0 0 100 100\" fill=\"none\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M50 12v76M12 50h76M23 23l54 54M23 77l54-54\" stroke=\"currentColor\" stroke-width=\"10\" stroke-linecap=\"round\"/></svg>");
const offlineSupported=Boolean(navigator.serviceWorker?.register);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>d?label('{date}',{date:{date:d,format:'short'}}):'—';
const titles={overview:'Your clinic, at a glance.',mothers:'Mothers’ records',children:'Children’s records',visits:'Visits & notes',vaccines:'Vaccinations',growth:'Child growth',inventory:'Vaccine inventory',guides:'Care guides',backup:'Data & backup',access:'Patient access',tasks:'Clinic tasks'};
const singles={mothers:'maternal profile',children:'child profile',visits:'visit',vaccines:'vaccination',growth:'measurement',inventory:'vaccine batch',guides:'clinic guide'};
const descriptions={mothers:'Every mother, a story worth keeping close.',children:'Small beginnings. A growing care story.',visits:'Checkups, symptoms, food intake, and the details that matter.',vaccines:'Vaccination schedules and history, connected to each family record.',growth:'Measurements over time, with your own assessment notes.',inventory:'Batch-level stock, low-stock thresholds, and expiration dates.'};
let store=null;
let listPage=1,listSort='default',locationFilter='',accessRender=0;
const staff=()=>store?.account.role==='staff';
const companion=()=>!staff()&&store?.account.kind==='father';
const accountUI=setupAccounts(next=>{store=next;store.onRemap=reconcileProfileIds;route();window.scrollTo(0,0);});
let page='overview',subpage='records',profileId=null,query='',filter='All',editing=null,importStage=null,installEvent=null,toastTimer,offlineReady=false;
let lastFocus=null,infoLastFocus=null,formBaseline='',vaccinationRefreshAt=0,readingGuideId=null,readingGuidePreview=null,taskKind='requests';
const data=()=>store?.data??emptyData();

function reconcileProfileIds(mapping){
 if(profileId&&mapping[profileId]&&mapping[profileId]!==profileId){profileId=mapping[profileId];history.replaceState(null,'','#workspace/'+page+'/'+profileId+(['mothers','children'].includes(page)&&subpage!=='records'?'/'+subpage:''));}
 if(!editing)return;
 if(editing.id&&mapping[editing.id]){editing.id=mapping[editing.id];if($('#field-id'))$('#field-id').value=editing.id;}
 if(editing.before?.id)editing.before.id=mapping[editing.before.id]??editing.before.id;
 if(editing.before?.patient)editing.before.patient=mapping[editing.before.patient]??editing.before.patient;
  if(editing.before?.motherId)editing.before.motherId=mapping[editing.before.motherId]??editing.before.motherId;
 const selector=$('#field-patient');if(selector)for(const option of selector.options){const previous=option.value;if(mapping[previous]&&mapping[previous]!==previous){option.value=mapping[previous];option.textContent=option.textContent.replace(new RegExp(previous+'$'),mapping[previous]);}}
  const motherSelector=$('#field-motherId');if(motherSelector)for(const option of motherSelector.options){const previous=option.value;if(mapping[previous]&&mapping[previous]!==previous){option.value=mapping[previous];option.textContent=option.textContent.replace(new RegExp(previous+'$'),mapping[previous]);}}
  if(formBaseline){const baseline=JSON.parse(formBaseline);if(baseline.patient)baseline.patient=mapping[baseline.patient]??baseline.patient;if(baseline.motherId)baseline.motherId=mapping[baseline.motherId]??baseline.motherId;if(baseline.id)baseline.id=mapping[baseline.id]??baseline.id;formBaseline=JSON.stringify(baseline);}
}
$('.skip-link').addEventListener('click',e=>{e.preventDefault();const target=!$('#auth-view').hidden?$('#auth-main'):$('#workspace-view').hidden?$('#main'):$('#workspace-main');target.tabIndex=-1;target.focus();});
function toast(message){clearTimeout(toastTimer);setText($('#toast'),message);$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
function info(title,body){readingGuideId=null;readingGuidePreview=null;infoLastFocus=document.activeElement;setText($('#info-title'),title);$('#info-body').innerHTML=body;$('#info-dialog').showModal();}

$('#open-profile').onclick=()=>{$('#open-profile').setAttribute('aria-expanded','true');$('#profile-dialog').showModal();};
$('#close-profile').onclick=()=>$('#profile-dialog').close();
$('#profile-dialog').addEventListener('close',()=>{$('#open-profile').setAttribute('aria-expanded','false');if(store)$('#open-profile').focus();});
$('#profile-dialog').addEventListener('click',event=>{if(event.target!==event.currentTarget)return;const box=event.currentTarget.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)event.currentTarget.close();});

$('#open-companion').onclick=async()=>{const active=store;$('#profile-dialog').close();info('Companion access',markup('<p>Loading companion access…</p>'));try{const result=await api('family',{proof:active.proof});if(store!==active||!$('#info-dialog').open)return;active.family=result.family;$('#info-body').innerHTML=companionSettings(active);mountFamily($('#info-body'),active,()=>{$('#info-dialog').close();route();});}catch(error){if(store===active&&$('#info-dialog').open)$('#info-body').innerHTML=ui`<p class="notice warning">${label(error.message)}</p>`;}};
$('#close-info').onclick=()=>$('#info-dialog').close();
$('#info-dialog').addEventListener('close',()=>{const focus=document.contains(infoLastFocus)?infoLastFocus:$('#workspace-view').hidden?$('#hero-title'):$('#page-content h1');if(focus){if(focus.tagName==='H1')focus.tabIndex=-1;focus.focus({preventScroll:true});}});
function updateStorageNotice(){$('#open-companion').hidden=staff()||store.account.kind!=='mother';const warning=$('#storage-warning');setText(warning,[store.error,store.sessionWarning].filter(Boolean).map(x=>t(x)).join(' '));warning.hidden=!warning.textContent;setText($('#sync-status'),store.message);$('#account-label').textContent=store.account.displayName+' · '+t(staff()?'Clinic staff':companion()?'Father / companion':'Mother');const initials=store.account.displayName.trim().split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase();$('#profile-initials').textContent=initials;$('#menu-initials').textContent=initials;$('#profile-username').textContent='@'+store.account.username;$('.profile-status-dot').dataset.state=store.pending?'pending':navigator.onLine?'connected':'offline';}

const vaccineNameKey=value=>String(value??'').normalize('NFC').trim().replace(/\s+/gu,' ').toLowerCase();
const patientLabel=id=>{const p=patientById(data(),id);return p?`${p.name} · ${p.id}`:id;};
const provenance=r=>r.updatedByRole?ui`<small class="record-provenance">${label(r.updatedByRole==='patient'?'Patient-entered':'Staff updated')}</small>`:'';
const badge=s=>ui`<span class="badge ${['Overdue','Expired','Rejected'].includes(s)?'danger':['Due today','Low stock','Follow-up needed','Pending verification','Needs staff review','Approval awaiting sync','Request awaiting sync'].includes(s)?'warning':['Inactive','Not assessed'].includes(s)?'muted':''}">${label(s)}</span>`;
function heading(title,description='',button='',rawTitle=false){return ui`<div class="page-heading"><div><p class="eyebrow">KASAMA MO SA PAG-AALAGA.</p><h1>${rawTitle?escape(title):label(title)}</h1>${description?ui`<p>${label(description)}</p>`:''}</div>${button}</div>`;}
function addButton(type,buttonLabel){if(companion())return '';if(!staff()&&type==='mothers'&&(store.account.kind==='mother'||data().mothers.length))return '';if(!staff()&&type==='inventory')return '';if(type==='vaccines')buttonLabel=staff()?'Approve vaccination':'Request vaccination';return ui`<button class="button primary" data-add="${type}">+ ${label(buttonLabel??`Add ${singles[type]}`)}</button>`;}
function editButton(type,id,buttonLabel='View & edit'){if(companion())return type==='vaccines'?ui`<button class="row-button" data-vaccine-details="${escape(id)}">View details ↗</button>`:ui`<button class="row-button" data-view="${type}" data-id="${escape(id)}">View details ↗</button>`;if(type==='vaccines'&&!staff()){const record=data().vaccines.find(item=>item.id===id);if(record?.approvalStatus!=='Pending verification')return ui`<button class="row-button" data-vaccine-details="${escape(id)}">View details ↗</button>`;buttonLabel='Edit request';}return ui`<button class="row-button" data-edit="${type}" data-id="${escape(id)}" aria-label="${escape(t(buttonLabel)+' '+(data()[type].find(r=>r.id===id)?.name??singles[type]))}" data-ui-attrs="${escape(JSON.stringify({'aria-label':{key:'{action} {name}',params:{action:{ui:buttonLabel},name:data()[type].find(r=>r.id===id)?.name??t(singles[type])}}}))}">${label(buttonLabel)} ↗</button>`;}
function table(headers,rows){return ui`<div class="table-wrap"><table><thead><tr>${headers.map(h=>ui`<th scope="col">${label(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(cells=>ui`<tr>${cells.map((c,i)=>ui`<td data-label="${escape(t(headers[i]))}" data-ui-attrs="${escape(JSON.stringify({'data-label':headers[i]}))}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function empty(type,searching=false){return ui`<div class="empty-state"><span class="empty-mark" aria-hidden="true">${type==='children'?FLOWER:'♡'}</span><h2>${label(searching?'No matching records.':type==='mothers'?'A place for every mother.':type==='children'?'A place for every little one.':'A place for every care detail.')}</h2><p>${searching?label('Try another name, ID, or filter.'):label('Your {section} will appear here. Start with a {record}.',{section:{ui:titles[type]},record:{ui:singles[type]}})}</p>${searching?markup('<button class="button secondary" id="clear-search">Clear filters</button>'):addButton(type)}</div>`;}
function renderOverview(){
 if(!staff())return renderPatientOverview();
 return heading(titles.overview,'Start with the records that need a decision or follow-up.',addButton('mothers','Add a profile'))+renderStaffDashboard(data());
}
function rowCells(type,r){
 if(type==='mothers')return [ui`<strong><a class="profile-name-link" href="#workspace/${type}/${escape(r.id)}">${escape(r.name)}</a></strong>${provenance(r)}<small>${escape(r.id)}${r.barangay?' · '+escape(r.barangay):''}</small>`,`${r.age} ${label('years')}`,fmt(r.edd),badge(r.status),editButton(type,r.id)];
  if(type==='children')return [ui`<strong><a class="profile-name-link" href="#workspace/${type}/${escape(r.id)}">${escape(r.name)}</a></strong>${provenance(r)}<small>${escape(r.id)} · ${label(r.gender)}</small>`,`${fmt(r.dob)}<small>${ageMonths(r.dob)} ${label('months')}</small>`,motherReference(r),badge(r.status),editButton(type,r.id)];
 if(type==='visits')return [ui`<strong>${escape(patientLabel(r.patient))}</strong>${provenance(r)}<small>${fmt(r.date)}</small>`,`${escape(r.notes.slice(0,110))}${r.notes.length>110?'…':''}`,r.followUp?fmt(r.followUp):'—',editButton(type,r.id)];
 if(type==='vaccines')return [ui`<strong>${escape(patientLabel(r.patient))}</strong><small>${escape(r.vaccine)} · ${escape(r.dose)}</small>${provenance(r)}${r.stockUse?ui`<small>${label(r.stockUse.kind==='reserved'?(hasPendingVaccination(r.id)?'Reservation awaiting sync':'1 dose reserved'):'1 clinic dose used')}</small>`:''}`,fmt(r.scheduled),r.administered?fmt(r.administered):'—',ui`${r.approvalStatus==='Approved'&&!r.administered&&!hasPendingVaccination(r.id)&&['Overdue','Due today'].includes(vaccineStatus(r))?badge('Approved'):''}${badge(displayVaccineStatus(r))}`,editButton(type,r.id)];
 if(type==='growth')return [ui`<strong>${escape(patientLabel(r.patient))}</strong>${provenance(r)}<small>${fmt(r.date)}</small>`,`${r.weight} kg`,`${r.height} cm`,badge(r.assessment),editButton(type,r.id)];
 return [ui`<strong>${escape(r.vaccine)}</strong><small>${label('Batch')} ${escape(r.batch)}</small>`,`${r.stock} ${label('doses')}<small>${label('Alert at {count} or fewer',{count:r.threshold})}</small><small>${label('{count} reserved',{count:data().vaccines.filter(v=>v.stockUse?.batchId===r.id&&v.stockUse.kind==='reserved').length})}</small>`,fmt(r.expires),badge(stockStatus(r)),ui`<div class="row-actions">${editButton(type,r.id)}${r.stock>0&&r.expires>=today()?ui`<button class="row-button" data-schedule-batch="${escape(r.id)}">Assign dose ↗</button>`:''}</div>`];
}
function motherReference(child){const mother=data().mothers.find(m=>m.id===child.motherId);return mother?ui`<a class="mother-profile-link" href="#workspace/mothers/${escape(mother.id)}">${escape(mother.name)} · ${escape(mother.id)} ↗</a>`:escape(child.motherName);}
const headers={mothers:['Mother','Age','Expected delivery','Status','Actions'],children:['Child','Date of birth','Mother','Status','Actions'],visits:['Patient','Visit notes','Follow-up','Actions'],vaccines:['Patient & vaccine','Scheduled','Administered','Status','Actions'],growth:['Child','Weight','Length / height','Assessment','Actions'],inventory:['Vaccine & batch','Stock','Expiration','Status','Actions']};
function recordStatus(type,r){return type==='vaccines'?vaccineStatus(r):type==='inventory'?stockStatus(r):type==='growth'?r.assessment:r.status??'';}
const effectiveType=()=>['mothers','children'].includes(page)&&subpage!=='records'?subpage:page;
function scopedRecords(type){let records=data()[type];if(['visits','vaccines','growth'].includes(type)){if(profileId)records=records.filter(r=>r.patient===profileId);else if(['mothers','children'].includes(page)){const ids=new Set(data()[page].map(p=>p.id));records=records.filter(r=>ids.has(r.patient));}}return records;}
function filtered(type){
 const items=scopedRecords(type).filter(r=>(filter==='All'||recordStatus(type,r)===filter)&&(!locationFilter||r.barangay===locationFilter)&&searchText(Object.values({...r,patient:patientLabel(r.patient??'')}).join(' ')).includes(searchText(query)));
 if(type==='vaccines')return items;
 return orderItems(items,listSort==='default'?(['visits','growth'].includes(type)?'date-newest':'name'):listSort,r=>r.name??r.vaccine??patientLabel(r.patient??''),r=>r.date??r.expires??r.edd??r.dob??'');
}

const isApprovedVaccination=record=>(!record.approvalStatus||record.approvalStatus==='Approved')&&!vaccinationNeedsReview(record);
const hasPendingVaccination=id=>store.pending?.batches?.some(batch=>batch.operations.some(op=>op.type==='vaccines'&&(op.record.id===id||op.originalId===id)));
function displayVaccineStatus(record){if(hasPendingVaccination(record.id)){if(record.approvalStatus==='Approved')return 'Approval awaiting sync';if(record.approvalStatus==='Pending verification')return 'Request awaiting sync';}return vaccineStatus(record);}
function requestSummary(){const items=data().vaccines.filter(vaccinationNeedsReview);if(staff())return items.length?ui`<a class="notice request-summary" href="#workspace/vaccines">${label('{count} vaccination requests need staff review.',{count:items.length})} <span>Review requests ↗</span></a>`:'';return ui`<section class="panel request-summary-panel"><div><h2>Vaccination requests</h2><p>${label('{count} requests awaiting verification',{count:items.length})}</p></div>${addButton('vaccines')}</section>`;}
function requestActions(record){if(companion())return editButton('vaccines',record.id);if(staff())return ui`<button class="row-button" data-review-vaccination="${escape(record.id)}">Review request ↗</button>`;return ui`<div class="row-actions">${editButton('vaccines',record.id)}${record.approvalStatus==='Pending verification'?ui`<button class="row-button" data-cancel-vaccination="${escape(record.id)}">Cancel request</button>`:''}</div>`;}
function renderVaccinationResults(){
 const items=filtered('vaccines'),requests=items.filter(record=>!isApprovedVaccination(record)).sort((a,b)=>Number(!vaccinationNeedsReview(a))-Number(!vaccinationNeedsReview(b))),approved=items.filter(isApprovedVaccination);
 return ui`${!staff()&&store.pending&&store.error?markup('<section class="notice warning request-recovery"><strong>Your pending changes need review.</strong><p>The clinic may have reviewed this request while your device was offline. Download your private pending copy before replacing local edits with the clinic decision.</p><div class="button-stack"><button class="button secondary" id="download-patient-pending">Download my pending copy</button><button class="button secondary" id="load-patient-decision">Load clinic decision & replace local edits</button></div></section>'):''}<p class="record-count">${label('{shown} of {total} records',{shown:items.length,total:scopedRecords('vaccines').length})}</p><section class="vaccination-section request-section" aria-labelledby="requests-title"><div class="vaccination-section-heading"><h2 id="requests-title">${label(staff()?'Requests to review':'Your vaccination requests')}</h2><span class="request-count">${requests.filter(vaccinationNeedsReview).length}</span></div><p class="data-note">${label(staff()?'Check the patient, choose a batch and appointment date, then approve or explain a declined request.':'A request is not an appointment. Wait for staff approval before visiting for this vaccination.')}</p>${requests.length?table(['Patient & vaccine','Preferred date','Request status','Staff response','Actions'],requests.map(record=>[ui`<strong>${escape(patientLabel(record.patient))}</strong><small>${escape(record.vaccine)}${record.dose?' · '+escape(record.dose):''}</small>${record.requestNotes?ui`<small>${label('Patient message')}: ${escape(record.requestNotes)}</small>`:''}${!record.approvalStatus?markup('<small>Existing vaccination record, awaiting staff verification.</small>'):''}${hasPendingVaccination(record.id)?markup('<small>Saved on this device; waiting for clinic sync.</small>'):''}`,fmt(record.preferredDate),badge(displayVaccineStatus(record)),escape(record.reviewNotes||'—'),requestActions(record)])):markup('<div class="request-empty">No requests in this view.</div>')}</section><section class="vaccination-section" aria-labelledby="approved-title"><div class="vaccination-section-heading"><h2 id="approved-title">Approved appointments & vaccination history</h2></div>${approved.length?table(headers.vaccines,approved.map(record=>rowCells('vaccines',record))):markup('<div class="request-empty">Approved appointments and staff-recorded vaccination history will appear here.</div>')}</section>`;
}
function renderVaccinations(withHeading){
 const statuses=['Pending verification','Needs staff review','Approved / scheduled','Due today','Overdue','Completed','Rejected','Cancelled','Upcoming'];
 return (withHeading?heading('Vaccinations',staff()?'Review family requests and manage approved clinic doses.':'Request a vaccination and follow your clinic’s decision.',addButton('vaccines')):ui`<div class="section-actions">${addButton('vaccines')}</div>`)+markup('<p class="notice good">Request → staff verification → approved appointment → administered. Approval reserves one available clinic dose. Administration does not deduct it again.</p>')+ui`<div class="toolbar"><label class="search-box"><span>Search vaccinations</span><input id="record-search" type="search" placeholder="Search name, ID, or details…" value="${escape(query)}"></label><label><span>Filter by status</span><select id="record-filter"><option value="All">All</option>${statuses.map(status=>ui`<option value="${escape(status)}" ${filter===status?'selected':''}>${label(status)}</option>`).join('')}</select></label></div><div id="record-results">${renderVaccinationResults()}</div>`;
}
function showVaccinationDetails(record){const rows=[['Patient',escape(patientLabel(record.patient))],['Vaccine name',escape(record.vaccine)],['Dose / schedule label',escape(record.dose||'—')],['Status',badge(displayVaccineStatus(record))],['Preferred date',fmt(record.preferredDate)],['Approved appointment date',fmt(record.scheduled)],['Date administered',fmt(record.administered)],['Message for the clinic',escape(record.requestNotes||'—')],['Staff response / reason',escape(record.reviewNotes||'—')],['Clinic notes',escape(record.notes||'—')]];info('Vaccination details',ui`<dl class="patient-details">${rows.map(([key,value])=>ui`<div><dt>${label(key)}</dt><dd>${value}</dd></div>`).join('')}</dl>`);}

function recordToolbar(type,opts){
 const mode=listSort==='default'?(['visits','growth'].includes(type)?'date-newest':'name'):listSort;
 const locations=['mothers','children'].includes(type)?[...new Set(scopedRecords(type).map(r=>r.barangay).filter(Boolean))].sort((a,b)=>a.localeCompare(b)):[];
 return ui`<div class="toolbar record-toolbar"><label class="search-box"><span>${label('Search {section}',{section:{ui:titles[type]}})}</span><input id="record-search" type="search" placeholder="Search name, ID, or details…" value="${escape(query)}"></label>${opts.length?ui`<label><span>Filter by status</span><select id="record-filter"><option value="All">All</option>${opts.map(s=>ui`<option value="${escape(s)}" ${filter===s?'selected':''}>${label(s)}</option>`).join('')}</select></label>`:''}<label><span>Sort records</span><select id="record-sort">${[['name','Name A–Z'],['name-desc','Name Z–A'],['id','Record ID'],['date-newest','Date: latest first'],['date-oldest','Date: earliest first']].map(([value,text])=>ui`<option value="${value}" ${mode===value?'selected':''}>${label(text)}</option>`).join('')}</select></label>${locations.length?ui`<label><span>Barangay / location</span><select id="record-location"><option value="">All locations</option>${locations.map(location=>ui`<option value="${escape(location)}" ${locationFilter===location?'selected':''}>${escape(location)}</option>`).join('')}</select></label>`:''}</div>`;
}
function recordResults(type){
 const items=filtered(type),view=pageItems(items,listPage);listPage=view.page;
 return ui`<p class="record-count">${label('Showing {start}–{end} of {total} records',{start:view.start,end:view.end,total:view.total})}</p>${items.length?table(headers[type],view.items.map(r=>rowCells(type,r))):empty(type,!!query||filter!=='All'||!!locationFilter)}${pagination(view,'records')}`;
}
function renderRecords(type,withHeading=true){
 if(type==='vaccines')return renderVaccinations(withHeading);
 const opts=type==='mothers'||type==='children'?['Active','Inactive']:type==='vaccines'?['Overdue','Due today','Upcoming','Completed']:type==='inventory'?['Available','Low stock','Expired']:type==='growth'?['Not assessed','Reviewed','Follow-up needed']:[];

 let html=withHeading?heading(titles[type],descriptions[type],addButton(type)):ui`<div class="section-actions">${addButton(type)}</div>`;
 if(type==='vaccines')html+=markup('<p class="notice good">Record dates agreed with your health worker. Patient updates are marked patient-entered. Clinic doses are connected to staff-managed vaccine stock.</p>');
 if(type==='inventory')html+=markup('<p class="data-note">Available doses exclude approved reservations. Offline stock changes are confirmed after clinic sync.</p>');
 if(type==='growth')html+=markup('<p class="notice good">Patients and staff can record measurements and follow-up notes. The chart shows recorded weight over time; it does not calculate malnutrition diagnoses or WHO z-scores.</p>');
 html+=recordToolbar(type,opts)+ui`<div id="record-results">${recordResults(type)}</div>`;
 if(type==='growth'&&scopedRecords('growth').length)html+=ui`<section class="growth-chart"><h2 class="section-title">A child's growth story</h2><label for="chart-patient">Choose a child</label><select id="chart-patient">${data().children.filter(c=>(!profileId||c.id===profileId)&&data().growth.some(g=>g.patient===c.id)).map(c=>ui`<option value="${escape(c.id)}">${escape(c.name)} · ${c.id}</option>`).join('')}</select><div id="chart-content"></div></section>`;
 return html;
}
function refreshResults(){const type=effectiveType();$('#record-results').innerHTML=type==='vaccines'?renderVaccinationResults():recordResults(type);}
function renderChart(id){const items=data().growth.filter(r=>r.patient===id).sort((a,b)=>a.date.localeCompare(b.date));if(!items.length)return;
 const start=new Date(items[0].date).getTime(),end=new Date(items.at(-1).date).getTime();
 const max=Math.max(...items.map(r=>r.weight))+1,min=Math.max(0,Math.min(...items.map(r=>r.weight))-1);
 const pts=items.map(r=>({x:60+(end===start?230:(new Date(r.date).getTime()-start)/(end-start)*450),y:155-(r.weight-min)/(max-min)*125,r}));
 $('#chart-content').innerHTML=ui`<svg viewBox="0 0 550 190" role="img" aria-label="Recorded weight in kilograms over measurement dates. Exact values are in the table below."><path d="M55 20V160H525" stroke="var(--border)" fill="none"/><text x="5" y="30" fill="var(--text-secondary)" font-size="11">${max.toFixed(1)} kg</text><text x="5" y="160" fill="var(--text-secondary)" font-size="11">${min.toFixed(1)} kg</text><polyline points="${pts.map(p=>`${p.x},${p.y}`).join(' ')}" stroke="var(--primary)" fill="none" stroke-width="2.5"/>${pts.map(p=>ui`<circle cx="${p.x}" cy="${p.y}" r="4" fill="var(--primary)"><title>${fmt(p.r.date)}: ${p.r.weight} kg</title></circle>`).join('')}<text x="55" y="185" fill="var(--text-secondary)" font-size="10">${fmt(items[0].date)}</text>${items.length>1?ui`<text x="525" y="185" fill="var(--text-secondary)" text-anchor="end" font-size="10">${fmt(items.at(-1).date)}</text>`:''}</svg><p>Recorded weight only. A connected line is not a prediction or a reference growth standard.</p>${table(['Date','Weight','Length / height'],items.map(r=>[fmt(r.date),`${r.weight} kg`,`${r.height} cm`]))}`;
}
function renderBackup(){return heading('Keep a copy close.','Clinic records, with an encrypted offline copy for your account.')+ui`<p class="notice good">Cloud records are shared between authorized accounts. Offline edits remain pending until accepted by the server. If another device changes the clinic first, export your pending copy and review it before replacing anything.</p><div class="backup-grid"><section class="panel"><h2>Complete clinic backup</h2><p>Includes family records, care histories, vaccine stock and clinic guides. Downloaded backups are plain text: store them privately.</p><div class="button-stack"><button class="button primary" id="download-backup">Download backup ↧</button><button class="button secondary" id="persist-storage">Keep device storage</button></div></section><section class="panel"><h2>Restore or import</h2><p>Review a backup or Java text file before replacing clinic records. Old device records are never uploaded automatically.</p><label for="import-kind">File type</label><select id="import-kind"><option value="backup">Complete web backup (.json)</option><option value="mothers">Java maternal profiles (.txt)</option><option value="children">Java child profiles (.txt)</option></select><label for="import-file">Choose a file to review</label><input id="import-file" type="file" accept=".json,application/json"><button class="button secondary" id="review-legacy">Review records from the previous app</button><div id="import-preview" class="import-preview" aria-live="polite"></div></section><section class="panel"><h2>Java compatibility</h2><p>Only original profile fields fit Java text files. Contacts, barangay, visits and other care data require the complete backup.</p><div class="button-stack"><button class="button secondary" data-export="mothers">Maternal .txt ↧</button><button class="button secondary" data-export="children">Child .txt ↧</button></div></section><section class="panel"><h2>Refresh from the clinic</h2><p>Refreshing requires an online sign-in. Pending changes are preserved unless you explicitly choose to replace them. Download a backup first.</p><div class="button-stack"><button class="button secondary" id="reload-storage">Load latest clinic copy</button><button class="button secondary" id="discard-pending">Replace pending copy from cloud</button><button class="button secondary install-action">Install on this device ↗</button></div></section></div>`;}
