function updateVaccineSource(){
 const decision=$('#field-approvalStatus')?.value??'Approved',approved=decision==='Approved',batchSelect=$('#field-batchId');if(!batchSelect)return;
 const request=editing?.before?.approvalStatus==='Pending verification';
 const source=$('#field-stockMode');if(request&&approved)source.value='clinic';source.disabled=!approved||request;source.closest('.field').hidden=!approved||request;
 const clinic=approved&&source.value==='clinic';
 batchSelect.disabled=!clinic;batchSelect.required=clinic;batchSelect.closest('.field').hidden=!clinic;
 for(const key of ['scheduled','administered','dose','notes']){const element=$('#field-'+key);if(!element)continue;element.disabled=!approved;element.closest('.field').hidden=!approved;if(['scheduled','dose'].includes(key))element.required=approved;}
 const reason=$('#field-reviewNotes');reason.required=decision==='Rejected';
 const batch=data().inventory.find(item=>item.id===batchSelect.value),vaccine=$('#field-vaccine');vaccine.readOnly=request||clinic&&Boolean(batch);if(clinic&&batch&&!request)vaccine.value=batch.vaccine;
 if(!$('#stock-explanation'))$('#form-fields').insertAdjacentHTML('beforeend','<p id="stock-explanation" class="stock-hint"></p>');
 const alreadyAllocated=Boolean(editing?.before?.stockUse);
 setText($('#stock-explanation'),!approved?'Pending and declined requests do not reserve stock. Cancelling an unused approved appointment returns its reserved dose.':!clinic?'A vaccination recorded elsewhere does not use clinic stock.':alreadyAllocated?'This record already has a clinic dose allocated. Recording administration will not deduct another dose.':'Approving this appointment reserves one dose and deducts it from available stock. Recording administration later will not deduct it again.');
 setText($('#record-submit-label'),!approved?decision==='Rejected'?'Decline request':decision==='Cancelled'?'Cancel appointment':'Save pending request':clinic&&!alreadyAllocated?'Approve & reserve 1 dose':$('#field-administered')?.value?'Save administered dose':'Save approved appointment');
}

