 catch(error){setText($('#form-error'),error.message);$('#form-error').hidden=false;if(error.field){const el=$(`#field-${error.field}`);if(el){el.setAttribute('aria-invalid','true');setText($(`#error-${error.field}`),error.message);el.focus();}}}
